package equivalent;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ClonePair8992DifferenceFindingTest {

    private final ClonePair8992 subject = new ClonePair8992();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: exception.
     * Difference manifestation: the methods differ in thrown exceptions or normal completion.
     */
    @Test
    @BehavioralDifference(DifferenceType.EXCEPTION)
    void methodsDisagreeOnATableWhoseOnlyRowIsNull() {
        // method1 never dereferences the first row when there is no other row to compare it with,
        // whereas method2 reads the length of the first row unconditionally.
        assertTrue(subject.method1(new double[][]{null}));
        assertThrows(NullPointerException.class, () -> subject.method2(new double[][]{null}));
    }
}
